#include <cstddef>
#include <iostream>
#include <utility>

class Buffer {
public:
    explicit Buffer(std::size_t size)
        : data_{size == 0 ? nullptr : new int[size]{}}, size_{size} {}
    ~Buffer() { delete[] data_; }
    Buffer(const Buffer& other) : Buffer{other.size_} {
        for (std::size_t i = 0; i < size_; ++i) data_[i] = other.data_[i];
    }
    Buffer& operator=(const Buffer& other) {
        if (this != &other) {
            Buffer copy{other};
            swap(copy);
        }
        return *this;
    }
    Buffer(Buffer&& other) noexcept : data_{other.data_}, size_{other.size_} {
        other.data_ = nullptr;
        other.size_ = 0;
    }
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            size_ = other.size_;
            other.data_ = nullptr;
            other.size_ = 0;
        }
        return *this;
    }
    std::size_t size() const { return size_; }
    int get(std::size_t index) const { return data_[index]; }
    void set(std::size_t index, int value) { data_[index] = value; }
private:
    void swap(Buffer& other) noexcept {
        int* data = data_;
        data_ = other.data_;
        other.data_ = data;
        std::size_t size = size_;
        size_ = other.size_;
        other.size_ = size;
    }
    int* data_{};
    std::size_t size_{};
};

void show(const char* label, const Buffer& buffer) {
    std::cout << label << ':';
    for (std::size_t i = 0; i < buffer.size(); ++i) {
        std::cout << ' ' << buffer.get(i);
    }
    std::cout << '\n';
}

int main() {
    Buffer original{3};
    original.set(0, 4);
    original.set(1, 7);
    original.set(2, 9);
    Buffer copy{original};
    copy.set(0, 5);
    Buffer assigned{1};
    assigned = original;
    Buffer moved{std::move(copy)};
    assigned = std::move(moved);
    show("original", original);
    show("assigned", assigned);
    return 0;
}

